class Solution:
    def calDays(self, weights: list[int], capacity) -> int:
            d = 0
            curW = 0
            for w in weights:
                if curW + w > capacity:
                    d += 1
                    curW = 0
                curW += w
            return d + 1

    def shipWithinDays(self, weights: list[int], days: int) -> int:
        maxW, total = 0, 0
        for w in weights:
            if maxW < w:
                maxW = w
            total += w

        lo, hi = maxW, total
        ans = 0
        while lo <= hi:
            capacity = (lo + hi) // 2
            d = self.calDays(weights, capacity)
            if d <= days:
                ans = capacity
                hi = capacity - 1
            else:
                lo = capacity + 1

        return lo
